-- =============================================================================
-- Source seed script: Azure SQL (schema [rs]) for the recycling/diversion demo
-- Produces source tables whose columns match RS_DATA_PLATFORM.BRONZE exactly.
-- Safe to re-run: drops and recreates the three tables.
-- =============================================================================

IF OBJECT_ID('rs.FactPickupEvent','U') IS NOT NULL DROP TABLE rs.FactPickupEvent;
IF OBJECT_ID('rs.DimVehicle','U')      IS NOT NULL DROP TABLE rs.DimVehicle;
IF OBJECT_ID('rs.DimCustomer','U')     IS NOT NULL DROP TABLE rs.DimCustomer;
GO

IF SCHEMA_ID('rs') IS NULL EXEC('CREATE SCHEMA rs');
GO

CREATE TABLE rs.DimCustomer (
    CustomerId    INT           NOT NULL PRIMARY KEY,
    CustomerName  NVARCHAR(200) NULL,
    CustomerType  NVARCHAR(50)  NULL,
    Industry      NVARCHAR(100) NULL,
    ContractType  NVARCHAR(50)  NULL,
    City          NVARCHAR(100) NULL,
    Region        NVARCHAR(50)  NULL,
    CreatedAt     DATETIME2(3)  NULL,
    UpdatedAt     DATETIME2(3)  NULL,
    IsDeleted     BIT           NULL
);
GO

CREATE TABLE rs.DimVehicle (
    VehicleId     INT           NOT NULL PRIMARY KEY,
    VehicleNumber NVARCHAR(50)  NULL,
    VehicleType   NVARCHAR(50)  NULL,
    CapacityKg    INT           NULL,
    DepotCity     NVARCHAR(100) NULL,
    Region        NVARCHAR(50)  NULL,
    CreatedAt     DATETIME2(3)  NULL,
    UpdatedAt     DATETIME2(3)  NULL,
    IsDeleted     BIT           NULL
);
GO

CREATE TABLE rs.FactPickupEvent (
    PickupId          INT           NOT NULL PRIMARY KEY,
    CustomerId        INT           NULL,
    VehicleId         INT           NULL,
    PickupDate        DATE          NULL,
    WasteType         NVARCHAR(50)  NULL,
    WeightKg          FLOAT         NULL,
    RecycledWeightKg  FLOAT         NULL,
    LandfillWeightKg  FLOAT         NULL,
    PickupStatus      NVARCHAR(50)  NULL,
    CreatedAt         DATETIME2(3)  NULL,
    UpdatedAt         DATETIME2(3)  NULL,
    IsDeleted         BIT           NULL
);
GO

