-- ----- Verification -----
SELECT 'DimCustomer' AS TableName, COUNT(*) AS RowCnt FROM rs.DimCustomer
UNION ALL SELECT 'DimVehicle', COUNT(*) FROM rs.DimVehicle
UNION ALL SELECT 'FactPickupEvent', COUNT(*) FROM rs.FactPickupEvent;
GO
